const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path'),os=require('node:os'),cp=require('node:child_process');
const root=path.join(__dirname,'..'),context={TextEncoder};vm.createContext(context);vm.runInContext(fs.readFileSync(path.join(root,'manuals.js'),'utf8'),context);const api=context.RasnikiManuals;
const fields={title:'Example',purpose:'Repair',procedure:'Review the evidence',acceptance:'A clear outcome',rights:'Permissions',locations:'Declared only',review:'Open questions'};
for(const mode of Object.keys(api.modes)){const draft=api.manual(mode,fields);assert(draft.includes('UNREVIEWED'));for(const value of Object.values(fields))assert(draft.includes(value));}
assert.throws(()=>api.manual('constructor',fields));assert.throws(()=>api.manual('unknown',fields));
assert.equal(api.rewrite('care care','care','repair').text,'repair repair');assert.equal(api.rewrite('Care care','care','').count,1);assert.equal(api.rewrite('a.b','.',':').text,'a:b');assert.throws(()=>api.rewrite('text','','x'));assert.throws(()=>api.rewrite('x'.repeat(100000),'x','xx'));
const graph=api.blueprint('studio | Studio | reader\ncore | Records |\nreader | Reader | core');assert.equal(graph.constructionOrder.join(','),'core,reader,studio');
for(const source of ['', 'a | A | missing', 'a | A | a', 'a | A | b\nb | B | a', 'a | A |\na | Duplicate |', 'a | A | b,b\nb | B |'])assert.throws(()=>api.blueprint(source));
assert.throws(()=>api.program('😀'.repeat(1024)));assert(api.program('').includes('signal r0 2 1'));
const folder=fs.mkdtempSync(path.join(os.tmpdir(),'rasniki-manuals-'));try{const source=path.join(folder,'message.kerot'),message='Care, repair 😀\n';fs.writeFileSync(source,api.program(message));const run=cp.spawnSync('python3',[path.join(root,'software/kerot.py'),'run',source]);assert.equal(run.status,0,run.stderr.toString());assert.equal(run.stdout.toString(),message);}finally{fs.rmSync(folder,{recursive:true,force:true});}
function element(){return {value:'',events:{},children:[],textContent:'',disabled:false,append(x){this.children.push(x);if(this.children.length===1)this.value=x.value},addEventListener(k,f){this.events[k]=f}};}
const ids=['mode','title','purpose','procedure','acceptance','rights','locations','review','generate','manual-output','manual-save','manual-status','source','find','replacement','rewrite','rewrite-output','rewrite-save','rewrite-status','message','program','program-output','program-save','program-status','blueprint','validate','blueprint-output','blueprint-save','blueprint-status'];const els=Object.fromEntries(ids.map(id=>[id,element()]));context.document={getElementById:id=>els[id],createElement:element};vm.runInContext(fs.readFileSync(path.join(root,'manuals-ui.js'),'utf8'),context);
els.title.value='Manual';els.generate.events.click();assert(els['manual-output'].textContent.includes('Manual'));assert.equal(els['manual-save'].disabled,false);els.title.events.input();assert.equal(els['manual-save'].disabled,true);
els.source.value='care';els.find.value='care';els.replacement.value='repair';els.rewrite.events.click();assert(els['rewrite-output'].textContent.endsWith('repair'));els.find.value='';els.rewrite.events.click();assert.equal(els['rewrite-save'].disabled,true);
els.blueprint.value='a | A |';els.validate.events.click();assert.equal(els['blueprint-save'].disabled,false);els.blueprint.value='a | A | a';els.validate.events.click();assert.equal(els['blueprint-save'].disabled,true);
console.log('Manual studio checks passed: editions, rewriting, bounds, blueprint ordering/cycles, real K0 UTF-8 execution, and UI result invalidation.');
